package com.google.gson.internal;

import java.io.*;
import java.io.ObjectInputStream;
import java.io.ObjectStreamClass;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class UnsafeAllocator_create_TriageGen2Test {

    @Test
    public void testCreate() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertTrue(allocator instanceof UnsafeAllocator);
    }

    @Test
    public void testCreateTryJvm() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        Method allocateInstance = UnsafeAllocator.class.getDeclaredMethod("allocateInstance", Class.class);
        allocateInstance.setAccessible(true);
        Object unsafe = UnsafeAllocator.class.getField("theUnsafe").get(null);
        assertTrue(allocateInstance.invoke(allocator, String.class) instanceof String);
    }

    @Test
    public void testCreateTryDalvikvmPostGingerbread() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        Method getConstructorId = ObjectStreamClass.class.getDeclaredMethod("getConstructorId", Class.class);
        getConstructorId.setAccessible(true);
        int constructorId = (int) getConstructorId.invoke(null, String.class);
        Method newInstance = ObjectStreamClass.class.getDeclaredMethod("newInstance", Class.class, int.class);
        newInstance.setAccessible(true);
        assertTrue(newInstance.invoke(null, String.class, constructorId) instanceof String);
    }

    @Test
    public void testCreateTryDalvikvmPreGingerbread() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        Method newInstance = ObjectInputStream.class.getDeclaredMethod("newInstance", Class.class, Class.class);
        newInstance.setAccessible(true);
        assertTrue(newInstance.invoke(null, String.class, Object.class) instanceof String);
    }

    @Test
    public void testCreateCatchAll() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        Method allocateInstance = UnsafeAllocator.class.getDeclaredMethod("allocateInstance", Class.class);
        allocateInstance.setAccessible(true);
        Object unsafe = UnsafeAllocator.class.getField("theUnsafe").get(null);
        try {
            allocateInstance.invoke(allocator, String.class);
            fail("Expected UnsupportedOperationException");
        } catch (Exception e) {
            assertTrue(e instanceof UnsupportedOperationException);
        }
    }

    @Test
    public void testCreateCatchAll2() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        Method getConstructorId = ObjectStreamClass.class.getDeclaredMethod("getConstructorId", Class.class);
        getConstructorId.setAccessible(true);
        int constructorId = (int) getConstructorId.invoke(null, String.class);
        Method newInstance = ObjectStreamClass.class.getDeclaredMethod("newInstance", Class.class, int.class);
        newInstance.setAccessible(true);
        try {
            newInstance.invoke(null, String.class, constructorId);
            fail("Expected UnsupportedOperationException");
        } catch (Exception e) {
            assertTrue(e instanceof UnsupportedOperationException);
        }
    }

    @Test
    public void testCreateCatchAll3() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        Method newInstance = ObjectInputStream.class.getDeclaredMethod("newInstance", Class.class, Class.class);
        newInstance.setAccessible(true);
        try {
            newInstance.invoke(null, String.class, Object.class);
            fail("Expected UnsupportedOperationException");
        } catch (Exception e) {
            assertTrue(e instanceof UnsupportedOperationException);
        }
    }
}
